package com.feoearth.easybook;
import android.content.Context;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Same contract asset as Web/Worker. Invalid content fails closed; never replaced with empty content. */
public final class DocumentModel {
 private static JSONObject contract;
 public static synchronized void initialize(Context c){if(contract!=null)return;try(java.io.InputStream in=c.getAssets().open("document-contract.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);contract=new JSONObject(out.toString("UTF-8"));}catch(Exception e){throw new IllegalStateException("Schema unavailable",e);}}
 static void fail(){throw new IllegalArgumentException("Invalid document schema v1");}
 static void keys(JSONObject o,String... allowed){Set<String> a=new HashSet<>(Arrays.asList(allowed));Iterator<String> it=o.keys();while(it.hasNext())if(!a.contains(it.next()))fail();}
 static boolean contains(JSONArray a,String s){for(int i=0;i<a.length();i++)if(s.equals(a.optString(i)))return true;return false;}
 static void attributes(JSONObject value,JSONObject rules,String... required)throws Exception{if(value==null){if(required.length>0)fail();return;}Set<String> req=new HashSet<>(Arrays.asList(required));for(String k:req)if(!value.has(k))fail();Iterator<String> it=value.keys();while(it.hasNext()){String k=it.next();if(!rules.has(k))fail();Object v=value.get(k);if(v==JSONObject.NULL&&!req.contains(k))continue;JSONArray r=rules.getJSONArray(k);String t=r.getString(0);boolean ok=true;switch(t){case "string":ok=v instanceof String&&((String)v).length()<=r.getInt(1);break;case "integer":ok=v instanceof Number&&((Number)v).doubleValue()==((Number)v).longValue()&&((Number)v).longValue()>=r.getLong(1)&&((Number)v).longValue()<=r.getLong(2);break;case "boolean":ok=v instanceof Boolean;break;case "asset":ok=v instanceof String&&((String)v).matches("sha256:[a-f0-9]{64}");break;case "color":ok=v instanceof String&&((String)v).matches("#[a-fA-F0-9]{6}");break;case "url":ok=v instanceof String&&((String)v).length()<=2048&&((String)v).matches("(?i)(https?://[^\\s<>]+|mailto:[^\\s<>]+)");break;case "target":ok=v==JSONObject.NULL||"_blank".equals(v);break;case "rel":ok=v==JSONObject.NULL||"noopener noreferrer nofollow".equals(v);break;case "null":ok=v==JSONObject.NULL;break;default:ok=false;}if(!ok)fail();}}
 public static JSONObject validate(JSONObject envelope)throws Exception{if(contract==null)throw new IllegalStateException("Schema not initialized");keys(envelope,"schemaVersion","doc");if(!(envelope.get("schemaVersion") instanceof Number)||envelope.getDouble("schemaVersion")!=1)fail();visit(envelope.getJSONObject("doc"),0,null,new int[]{0});if(envelope.toString().getBytes(StandardCharsets.UTF_8).length>contract.getInt("maxBytes"))fail();return envelope;}
 static void visit(JSONObject n,int depth,String parent,int[] count)throws Exception{keys(n,"type","attrs","content","text","marks");if(++count[0]>contract.getInt("maxNodes")||depth>contract.getInt("maxDepth"))fail();String type=n.getString("type");JSONObject nodes=contract.getJSONObject("nodes"),r=nodes.optJSONObject(type);if(r==null)fail();if(parent==null?!type.equals("doc"):!contains(nodes.getJSONObject(parent).getJSONArray("children"),type))fail();String[] required=type.equals("heading")?new String[]{"level"}:type.equals("taskItem")?new String[]{"checked"}:type.equals("image")?new String[]{"assetId"}:type.equals("attachment")?new String[]{"assetId","name","mime","size"}:new String[0];if(n.has("attrs")&&!(n.get("attrs") instanceof JSONObject))fail();attributes(n.optJSONObject("attrs"),r.getJSONObject("attrs"),required);
 if(type.equals("text")){if(!(n.get("text") instanceof String)||n.getString("text").isEmpty()||n.has("content"))fail();}else if(n.has("text"))fail();
 if(n.has("marks")){if(!type.equals("text")||"codeBlock".equals(parent))fail();JSONArray marks=n.getJSONArray("marks");Set<String> seen=new HashSet<>();for(int i=0;i<marks.length();i++){JSONObject m=marks.getJSONObject(i);keys(m,"type","attrs");String mt=m.getString("type");if(!seen.add(mt)||!contract.getJSONObject("marks").has(mt))fail();if(m.has("attrs")&&!(m.get("attrs") instanceof JSONObject))fail();attributes(m.optJSONObject("attrs"),contract.getJSONObject("marks").getJSONObject(mt),mt.equals("link")?new String[]{"href"}:mt.equals("textColor")||mt.equals("highlight")?new String[]{"color"}:new String[0]);}}
 JSONArray children=n.has("content")?n.getJSONArray("content"):new JSONArray();if(children.length()<r.getInt("min")||r.getJSONArray("children").length()==0&&n.has("content"))fail();if((type.equals("listItem")||type.equals("taskItem"))&&!children.getJSONObject(0).getString("type").equals("paragraph"))fail();for(int i=0;i<children.length();i++)visit(children.getJSONObject(i),depth+1,type,count);
 }
 public static String plain(JSONObject envelope)throws Exception{validate(envelope);return text(envelope.getJSONObject("doc"));}
 static String text(JSONObject n)throws Exception{String type=n.getString("type");if(type.equals("text"))return n.getString("text");if(type.equals("hardBreak"))return "\n";if(type.equals("attachment"))return n.getJSONObject("attrs").getString("name");JSONArray children=n.optJSONArray("content");StringBuilder out=new StringBuilder();if(children!=null)for(int i=0;i<children.length();i++){if(i>0&&Arrays.asList("doc","blockquote","bulletList","orderedList","taskList","listItem","taskItem").contains(type))out.append('\n');out.append(text(children.getJSONObject(i)));}return out.toString();}
 public static Set<String> assets(JSONObject envelope)throws Exception{validate(envelope);Set<String> ids=new HashSet<>();assetsIn(envelope.getJSONObject("doc"),ids);return ids;}
 static void assetsIn(JSONObject n,Set<String> ids)throws Exception{if(n.getString("type").equals("image")||n.getString("type").equals("attachment"))ids.add(n.getJSONObject("attrs").getString("assetId").substring(7));JSONArray children=n.optJSONArray("content");if(children!=null)for(int i=0;i<children.length();i++)assetsIn(children.getJSONObject(i),ids);}
}
